  var isX2 = scene === 3 ? true : preset === 0;
  var a = 1;
  function f(x) { return isX2 ? x * x : 2 * x + 1; }
  function df(x) { return isX2 ? 2 * x : 2; }
  var h = h0;
  if (scene === 1) {
    var shrink = 1 - 0.72 * Math.min(1, local);
    h = (h0 < 0 ? -1 : 1) * Math.max(0.01, Math.abs(h0) * shrink);
  } else if (scene === 2) {
    var side = local < 0.5 ? 1 : -1;
    var z = local < 0.5 ? local * 2 : (local - 0.5) * 2;
    h = side * Math.max(0.01, Math.abs(h0) * (1 - 0.88 * z));
  } else {
    var hs = [1, 0.5, 0.1, 0.01];
    h = hs[Math.min(3, Math.floor(local * 4))];
  }
  if (Math.abs(h) < 0.0001) h = 0.01;
  var xB = a + h, yA = f(a), yB = f(xB);
  var dy = yB - yA, slope = dy / h, tangent = df(a);
  var px0 = 80, py0 = 395, pw = 585, ph = 285;
  var xmin = -2, xmax = 4, ymin = -1, ymax = 10;
