  }
  ctx.fillStyle = '#f8fbff'; ctx.fillRect(0,0,W,H);
  text('从割线到切线：导数是瞬时变化率', 480, 28, 24, '#17324d', 'center');
  text('第' + scene + '幕：' + (scene===1?'两点确定割线':scene===2?'双侧逼近切线':'x² 的具体计算'), 48, 72, 19, '#6b3fa0');
  ctx.strokeStyle='#d4e1ec'; ctx.lineWidth=1; ctx.strokeRect(35,85,890,350);
