  for (var gy=0;gy<=10;gy+=2) line(X(xmin),Y(gy),X(xmax),Y(gy),'#e5edf3',1);
  line(X(xmin),Y(0),X(xmax),Y(0),'#334e68',2);
  line(X(0),Y(ymin),X(0),Y(ymax),'#334e68',2);
  for (gx=-2;gx<=4;gx++) text(String(gx),X(gx),Y(0)+18,14,'#526b7a','center');
  for (gy=0;gy<=10;gy+=2) text(String(gy),X(0)-12,Y(gy),14,'#526b7a','right');
  text('x',X(xmax)+12,Y(0),17,'#263238'); text('y',X(0),Y(ymax)-12,17,'#263238');
  ctx.save(); ctx.strokeStyle='#2878c8'; ctx.lineWidth=3; ctx.beginPath();
  var started=false;
  for (var i=0;i<=180;i++) { var xx=xmin+(xmax-xmin)*i/180, yy=f(xx); if (yy>=ymin-1 && yy<=ymax+1) { if(!started){ctx.moveTo(X(xx),Y(yy));started=true;}else ctx.lineTo(X(xx),Y(yy)); } }
