    text('f′(1)=2',700,326,20,'#6b3fa0');
    text('y−1=2(x−1)',700,356,18,'#2878c8');
  }
  if(mode===1) text(scene===3?'显示：代数化简':'显示：差商数值',480,414,17,'#6b3fa0','center');
  if(mode===2) text('显示：切线方程',480,414,17,'#6b3fa0','center');
  text('预设 '+(isX2?'① f(x)=x²，a=1':'② f(x)=2x+1，a=1')+'   |   时间 '+sec.toFixed(1)+' / 34 秒',480,458,17,'#263238','center');
  var boundedSlope = isFinite(slope) ? slope : 0;
  return {metrics:{scene:scene, h:h, delta_y:dy, secant_slope:boundedSlope, derivative:tangent, function:isX2?'x^2':'2x+1', progress:run}};
}
